// first that fits, as before. Forgotten when the window opens or closes.
static std::map<DWORD, DWORD> s_mapMt2009CubePick;

void Cube_pick (LPCHARACTER ch, DWORD dwRewardVnum)
{
	if (NULL == ch)
		return;
	if (0 == dwRewardVnum)
		s_mapMt2009CubePick.erase(ch->GetPlayerID());
	else
		s_mapMt2009CubePick[ch->GetPlayerID()] = dwRewardVnum;
}

static CUBE_DATA* Mt2009CubeFindPicked (LPCHARACTER ch, LPITEM *items, WORD npc_vnum)
{
	std::map<DWORD, DWORD>::const_iterator it = s_mapMt2009CubePick.find(ch->GetPlayerID());
	if (it != s_mapMt2009CubePick.end())
	{
		for (size_t i = 0; i < s_cube_proto.size(); ++i)
		{
			CUBE_DATA* pCube = s_cube_proto[i];
			if (1 == pCube->reward.size() && pCube->reward[0].vnum == it->second && pCube->can_make_item(items, npc_vnum))
				return pCube;
		}
	}
	return FN_find_cube(items, npc_vnum);
}

